@NullMarked
final class ReleasePayloadVerification {
  private static final java.lang.String LITERAL_RELEASE_MANIFEST_JSON = "RELEASE-MANIFEST.json";

  private static final java.lang.String LITERAL_DB_MIGRATION = "db/migration/";

